scwin.btn_listNo_onclick = function (e) {
    dma_selectNewListNoReq.set("spotIsuTrdMktTpCd", $c.session.getUserInfo("market")); //시장구분코드
    const sbmOptions = {
        id: "sbm_selectNewListNo",
        action: "/api/listing/lstproc/listinvstg-common/select-new-listno",
        method: "get",
        ref: "dma_selectNewListNoReq",
